Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

#[local] Abbreviation ASEGS := Asan.M.loaded_segments.
#[local] Abbreviation cellA := (cell Asan.M.loaded_segments).
#[local] Abbreviation wrA := (wr Asan.M.loaded_segments).
#[local] Abbreviation wokA := (wok Asan.M.loaded_segments).
#[local] Notation "'U' r" := (bv_unsigned r) (at level 10, r at level 9).

Definition art_drain_frame (M : word -> option byte) (sp : Z) (raw : word) (regs : bvmap 5 word) : word -> option byte := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S=0!1,1|600;!1+00|30;|21;!1,13}8!1,72|40;|31;!1,78|500;!1,7|42;!1,7|43;$M;R%~R1!1+2!1+0!1,12$sp;R+3$raw;R1$regs;R!2'441!4'55!4'55!4'55!4'55!4'55#4!2'6#36!2'80#2!2'6#3!1,77!2'80!2'9#1!3,:46vv,;!2'<46!2'6#3!1,7|48;!2'80!2'9#1!3,:49vv,;!2'<49!2'6#3!1,7:!2'80!2'9#1!3,:4;vv,;!2'<4;!2'6#3!1,7|508;!2'80!2'9#1!3,:4<vv,;!2'<4<").

(* [comment removed for export] *)
Definition art_drain_mem (M : word -> option byte) (sp : Z) (raw : word) (regs : bvmap 5 word) (c L F B bytes GL GB gbytes : Z) : word -> option byte :=
  let M2 := Wn 4 (art_drain_frame M sp raw regs) (0x166b70 + 152) 1 in
  let M3 := if GL =? 0 then Wn 8 (Wn 8 (Wn 8 M2 (0x166b70 + 176) B) (0x166b70 + 168) F) (0x166b70 + 160) L
            else Wn 8 (Wn 8 (Wn 8 M2 GB F) (0x166b70 + 160) (GL + L)) (0x166b70 + 176) B in
  Wn 1 (Wn 8 (Wn 8 (Wn 8 (Wn 8 (Wn 8 M3 c 0) (c + 8) 0) (c + 16) 0) (0x166b70 + 184) (gbytes + bytes)) (c + 24) 0) (0x166b70 + 152) 0.

Section FPX. Context {fx : PropExec.FPState}.

Lemma art_drain_pre : forall regs (M rom : word -> option byte) (raw : word) (sp c L F B bytes GL GB gbytes : Z),
  getr regs 1 = raw -> getr regs 2 = Z_to_bv 64 sp -> getr regs 10 = Z_to_bv 64 0x166b70 -> getr regs 11 = Z_to_bv 64 c ->
  0x6c0000 + 48 <= sp -> sp < 2 ^ 64 -> 0 <= c -> c + 32 < 2 ^ 64 -> (c + 32 <= 0x10000 \/ 0x6c0000 <= c) -> apart (sp - 48) 48 c 32 ->
  1 <= L < 2 ^ 63 -> 0 <= F < 2 ^ 64 -> 0 <= B < 2 ^ 64 -> 0 <= bytes -> 0 <= gbytes -> gbytes + bytes < 2 ^ 64 -> 0 <= GL -> GL + L < 2 ^ 63 ->
  (GL <> 0 -> 0x6c0000 <= GB /\ GB + 8 < 2 ^ 64 /\ apart (sp - 48) 48 GB 8 /\ apart c 32 GB 8 /\ wrA M GB 8) ->
  wrA M (sp - 48) 48 -> wrA M c 32 -> wrA M (0x166b70 + 152) 40 ->
  cellA M (0x166b70 + 152) 4 0 ->
  cellA M c 8 L -> cellA M (c + 8) 8 F -> cellA M (c + 16) 8 B -> cellA M (c + 24) 8 bytes ->
  cellA M (0x166b70 + 160) 8 GL -> (GL <> 0 -> cellA M (0x166b70 + 176) 8 GB) -> cellA M (0x166b70 + 184) 8 gbytes ->
  exists regs', msteps ASEGS (mkst regs (0x5c4f4 : word) M rom) (mkst regs' (0x5c5b8 : word) (art_drain_mem M sp raw regs c L F B bytes GL GB gbytes) rom)
